267	    /**
268	     * Validate and normalize the optional owner email in place.
269	     *
270	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
271	     * When present it must be a syntactically valid address; a valid address is
272	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
273	     * present but syntactically invalid, so the caller can reject with 400.
274	     */
275	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
276	        String email = ownerFieldsDto.getEmail();
277	        if (email == null || email.isBlank()) {
278	            ownerFieldsDto.setEmail(null);
279	            return true;
280	        }
281	        String normalized = email.trim().toLowerCase(Locale.ROOT);
282	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
283	            return false;
284	        }
285	        ownerFieldsDto.setEmail(normalized);
286	        return true;
287	    }
288	
289	    /**
290	     * Validate the optional owner postcode in place.
291	     *
292	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
293	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
294	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
295	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
296	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
297	     * when a postcode is present but malformed or out of range, so the caller can
298	     * reject with 400.
299	     */
300	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
301	        String postcode = ownerFieldsDto.getPostcode();
302	        if (postcode == null || postcode.isBlank()) {
303	            ownerFieldsDto.setPostcode(null);
304	            return true;
305	        }
306	        if (!postcode.matches("\\d{4}")) {
307	            return false;
308	        }
309	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
310	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
311	        if (range != null) {
312	            int value = Integer.parseInt(postcode);
313	            if (value < range[0] || value > range[1]) {
314	                return false;
315	            }
316	        }
317	        return true;
318	    }
319	
320	    /**
321	     * Normalize an owner address: trim, collapse each run of whitespace to a single
322	     * space, upper-case, and expand common street-type abbreviations
323	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
324	     * A {@code null} value normalizes to the empty string.
325	     */
326	    private static String normalizeAddress(String value) {
327	        if (value == null) {
328	            return "";
329	        }
330	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
331	        if (collapsed.isEmpty()) {
332	            return "";
333	        }
334	        String[] tokens = collapsed.split(" ");
335	        StringBuilder sb = new StringBuilder(collapsed.length());
336	        for (int i = 0; i < tokens.length; i++) {
337	            if (i > 0) {
338	                sb.append(' ');
339	            }
340	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
341	        }
342	        return sb.toString();
343	    }
344	
345	    /**
346	     * The contact portion of an owner's derived identity key: its normalized telephone and
347	     * email ('&lt;normalizedTelephone&gt;|&lt;email or empty&gt;'), i.e. the identity key
348	     * without the household segment. Two owners share an identity when this value is equal;
349	     * because the telephone is part of it, members of one household with different telephones
350	     * do not collide. A {@code null} email contributes the empty string.
351	     */
352	    private static String identityContact(Owner owner) {
353	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
354	        String email = owner.getEmail() == null ? "" : owner.getEmail();
355	        return telephone + "|" + email;
356	    }
