358	    /**
359	     * Normalize a telephone number to E.164 form.
360	     *
361	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
362	     * explicit leading {@code '+'} and country code it is kept; otherwise the
363	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
364	     * dropped from the national digits. The result must contain 8 to 15 digits
365	     * after the {@code '+'}, and — for a recognised country calling code — exactly
366	     * the national-number length that code mandates ({@code '+61'} => 9 national
367	     * digits, {@code '+1'} => 10).
368	     *
369	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
370	     *         the input is absent or cannot form a valid E.164 number.
371	     */
372	    private static String toE164(String raw) {
373	        if (raw == null) {
374	            return null;
375	        }
376	        String trimmed = raw.trim();
377	        boolean hasCountryCode = trimmed.startsWith("+");
378	        // Strip spaces, dashes and brackets.
379	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
380	        String digits;
381	        if (hasCountryCode) {
382	            // Keep the explicit country code; drop the leading '+' for validation.
383	            digits = stripped.substring(1);
384	        } else {
385	            // No country code: assume '+61' and drop a single leading '0'.
386	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
387	            digits = "61" + national;
388	        }
389	        if (!digits.matches("\\d{8,15}")) {
390	            return null;
391	        }
392	        // For a recognised country calling code, enforce the exact national-number length it
393	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
394	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
395	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
396	                .sorted((a, b) -> b.length() - a.length()).toList()) {
397	            if (digits.startsWith(countryCode)) {
398	                int nationalLength = digits.length() - countryCode.length();
399	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
400	                    return null;
401	                }
402	                break;
403	            }
404	        }
405	        return "+" + digits;
406	    }
