408	    /**
409	     * Count the existing owners whose first and last name match the given names,
410	     * compared case-insensitively. Used to record an owner's namesake count at the
411	     * moment before it is created.
412	     */
413	    private int countNamesakes(String firstName, String lastName) {
414	        return (int) this.clinicService.findAllOwners().stream()
415	            .filter(existing -> existing.getFirstName() != null
416	                && existing.getFirstName().equalsIgnoreCase(firstName)
417	                && existing.getLastName() != null
418	                && existing.getLastName().equalsIgnoreCase(lastName))
419	            .count();
420	    }
