422	    /**
423	     * Count the existing owners in the same household as the given owner, i.e. those sharing its
424	     * computed householdId (derived from the normalized last name and postcode). Used, together
425	     * with the owner being created, to derive the household size recorded on the owner.
426	     */
427	    private int countHouseholdMembers(Owner owner) {
428	        String householdId = ownerMapper.householdId(owner);
429	        return (int) this.clinicService.findAllOwners().stream()
430	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
431	            .count();
432	    }
