434	    /**
435	     * Find an existing owner that the given (not-yet-created) owner is a possible (soft) duplicate
436	     * of: one sharing the same last name (compared case-insensitively) and the same postcode, but
437	     * carrying a different normalized telephone. Owners without a postcode never match (the postcode
438	     * must be shared). When several existing owners match, the one with the lowest id is returned so
439	     * the result is deterministic. Returns {@code null} when there is no such match.
440	     */
441	    private Owner findPossibleDuplicate(Owner candidate) {
442	        if (candidate.getPostcode() == null) {
443	            return null;
444	        }
445	        return this.clinicService.findAllOwners().stream()
446	            .filter(existing -> existing.getLastName() != null
447	                && existing.getLastName().equalsIgnoreCase(candidate.getLastName())
448	                && candidate.getPostcode().equals(existing.getPostcode())
449	                && !candidate.getTelephone().equals(existing.getTelephone()))
450	            .min(java.util.Comparator.comparing(Owner::getId))
451	            .orElse(null);
452	    }
453	
454	    /**
455	     * Build the owner's customer code, formatted {@code '<REGION>-<HASH8>'}.
456	     *
457	     * <p>{@code REGION} is the region derived from the owner's postcode (see
458	     * {@link #deriveRegion}). {@code HASH8} is the first 8 upper-case hex characters of the
459	     * SHA-256 of the normalized telephone concatenated with the last name
460	     * (e.g. {@code 'NSW-1A2B3C4D'}).
461	     */
462	    private String customerCode(Owner owner) {
463	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
464	        String hash8 = sha256HexUpper(owner.getTelephone() + owner.getLastName(), 8);
465	        return region + "-" + hash8;
466	    }
467	
468	    /**
469	     * Derive the owner's region, preferring the postcode. The postcode is matched against
470	     * each region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only when
471	     * it is absent or in no known range does this fall back to the fixed city-to-region table
472	     * (see {@link OwnerMapper#CITY_REGION}), and finally {@code 'UNKNOWN'}.
473	     */
474	    private static String deriveRegion(String postcode, String city) {
475	        if (postcode != null && postcode.matches("\\d{4}")) {
476	            int value = Integer.parseInt(postcode);
477	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
478	                int[] range = entry.getValue();
479	                if (value >= range[0] && value <= range[1]) {
480	                    return entry.getKey();
481	                }
482	            }
483	        }
484	        return OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
485	    }
486	
487	    /**
488	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
489	     * bytes of {@code value}.
490	     */
491	    private static String sha256HexUpper(String value, int length) {
492	        try {
493	            byte[] digest = MessageDigest.getInstance("SHA-256")
494	                .digest(value.getBytes(StandardCharsets.UTF_8));
495	            StringBuilder sb = new StringBuilder(digest.length * 2);
496	            for (byte b : digest) {
497	                sb.append(String.format("%02X", b));
498	            }
499	            return sb.substring(0, length);
500	        }
501	        catch (NoSuchAlgorithmException e) {
502	            throw new IllegalStateException(e);
503	        }
504	    }
