507	     * Count the existing owners located in the given city, compared case-insensitively.
508	     * Used to derive the per-city 4-digit sequence in the customer code.
509	     */
510	    private int countOwnersInCity(String city) {
511	        return (int) this.clinicService.findAllOwners().stream()
512	            .filter(existing -> existing.getCity() != null
513	                && existing.getCity().equalsIgnoreCase(city))
514	            .count();
515	    }
