517	    /**
518	     * Count the existing owners whose registration date is the given (adjusted business) date.
519	     * Used to enforce the per-day sign-up limit.
520	     */
521	    private int countOwnersRegisteredOn(LocalDate date) {
522	        return (int) this.clinicService.findAllOwners().stream()
523	            .filter(existing -> date.equals(existing.getRegistrationDate()))
524	            .count();
525	    }
